CREATE TABLE administrators(user_id TEXT PRIMARY KEY REFERENCES users(id));
CREATE TABLE administrative_versions(kind TEXT NOT NULL,object_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>=0),PRIMARY KEY(kind,object_id));
CREATE TABLE administrative_events(id TEXT PRIMARY KEY,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,object_id TEXT NOT NULL,created_at TEXT NOT NULL,payload_json TEXT NOT NULL);
CREATE TRIGGER administrative_events_no_update BEFORE UPDATE ON administrative_events BEGIN SELECT RAISE(ABORT,'immutable administrative event'); END;
CREATE TRIGGER administrative_events_no_delete BEFORE DELETE ON administrative_events BEGIN SELECT RAISE(ABORT,'immutable administrative event'); END;
CREATE TABLE administrative_requests(user_id TEXT NOT NULL REFERENCES users(id),key TEXT NOT NULL,request_hash TEXT NOT NULL,event_id TEXT NOT NULL REFERENCES administrative_events(id),response_json TEXT NOT NULL,PRIMARY KEY(user_id,key));
CREATE TRIGGER administrative_requests_no_update BEFORE UPDATE ON administrative_requests BEGIN SELECT RAISE(ABORT,'immutable administrative request'); END;
CREATE TRIGGER administrative_requests_no_delete BEFORE DELETE ON administrative_requests BEGIN SELECT RAISE(ABORT,'immutable administrative request'); END;
INSERT INTO administrative_versions SELECT 'operator',id,0 FROM operators;
CREATE TRIGGER admin_version_operators_insert AFTER INSERT ON operators BEGIN INSERT INTO administrative_versions VALUES('operator',NEW.id,1) ON CONFLICT(kind,object_id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER admin_version_operators_update AFTER UPDATE ON operators BEGIN INSERT INTO administrative_versions VALUES('operator',NEW.id,1) ON CONFLICT(kind,object_id) DO UPDATE SET version=version+1; END;
INSERT INTO administrative_versions SELECT 'site',id,0 FROM sites;
CREATE TRIGGER admin_version_sites_insert AFTER INSERT ON sites BEGIN INSERT INTO administrative_versions VALUES('site',NEW.id,1) ON CONFLICT(kind,object_id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER admin_version_sites_update AFTER UPDATE ON sites BEGIN INSERT INTO administrative_versions VALUES('site',NEW.id,1) ON CONFLICT(kind,object_id) DO UPDATE SET version=version+1; END;
INSERT INTO administrative_versions SELECT 'location',id,0 FROM locations;
CREATE TRIGGER admin_version_locations_insert AFTER INSERT ON locations BEGIN INSERT INTO administrative_versions VALUES('location',NEW.id,1) ON CONFLICT(kind,object_id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER admin_version_locations_update AFTER UPDATE ON locations BEGIN INSERT INTO administrative_versions VALUES('location',NEW.id,1) ON CONFLICT(kind,object_id) DO UPDATE SET version=version+1; END;
INSERT INTO administrative_versions SELECT 'user',id,0 FROM users;
CREATE TRIGGER admin_version_users_insert AFTER INSERT ON users BEGIN INSERT INTO administrative_versions VALUES('user',NEW.id,1) ON CONFLICT(kind,object_id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER admin_version_users_update AFTER UPDATE ON users BEGIN INSERT INTO administrative_versions VALUES('user',NEW.id,1) ON CONFLICT(kind,object_id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER admin_version_role_assignments_insert AFTER INSERT ON role_assignments BEGIN UPDATE administrative_versions SET version=version+1 WHERE kind='user' AND object_id=NEW.user_id; END;
CREATE TRIGGER admin_version_role_assignments_delete AFTER DELETE ON role_assignments BEGIN UPDATE administrative_versions SET version=version+1 WHERE kind='user' AND object_id=OLD.user_id; END;
CREATE TRIGGER admin_version_administrators_insert AFTER INSERT ON administrators BEGIN UPDATE administrative_versions SET version=version+1 WHERE kind='user' AND object_id=NEW.user_id; END;
CREATE TRIGGER admin_version_administrators_delete AFTER DELETE ON administrators BEGIN UPDATE administrative_versions SET version=version+1 WHERE kind='user' AND object_id=OLD.user_id; END;
